/* ---------- helpers ---------- */
const $=s=>document.querySelector(s);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const TZ='Asia/Karachi';
const fDate=t=>new Intl.DateTimeFormat('en-GB',{timeZone:TZ,day:'2-digit',month:'2-digit',year:'numeric'}).format(t).replace(/\//g,'-');
const fTime=t=>new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'numeric',minute:'2-digit',hour12:true}).format(t);
const num=v=>{const n=parseFloat(v);return isFinite(n)?n:NaN};
const r2=n=>Math.round(n*100)/100;
const IC={home:'M3 11l9-8 9 8M5 10v10h14V10',cart:'M3 4h2l2.5 11h10L20 7H6M9 20h.01M17 20h.01',box:'M21 8l-9-5-9 5v8l9 5 9-5zM3 8l9 5 9-5M12 13v8',receipt:'M6 2h12v20l-3-2-3 2-3-2-3 2zM9 7h6M9 11h6',set:'M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0M14 4v4M8 10v4M16 16v4',trash:'M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3',plus:'M12 5v14M5 12h14',print:'M6 9V3h12v6M6 18H4v-7h16v7h-2M7 14h10v7H7z',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2M9 11a4 4 0 100-8 4 4 0 000 8zM22 21v-2a4 4 0 00-3-3.9M16 3.1a4 4 0 010 7.8',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',wallet:'M3 7h16a2 2 0 012 2v10a2 2 0 01-2 2H5a2 2 0 01-2-2zM3 7l2-3h12M16 14h2',tag:'M20 12l-8 8-9-9V3h8zM7.5 7.5h.01',layers:'M12 2l10 5-10 5L2 7zM2 17l10 5 10-5M2 12l10 5 10-5',dollar:'M12 2v20M17 6H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6'};
const ic=n=>`<svg class="ic" viewBox="0 0 24 24"><path d="${IC[n]}"/></svg>`;
const logoSVG=()=>`<svg viewBox="0 0 48 48" width="40" height="40"><rect width="48" height="48" rx="14" fill="#2563eb"/><path d="M13 19h22l-2 14H15zM18 19a6 6 0 0112 0" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="24" cy="26" r="2.8" fill="#fbbf24"/></svg>`;

/* ---------- storage ---------- */
const KEY='shopease_pos_v1';
const DEF={settings:{name:'AH Mart',address:'Main Bazaar, Islamabad, Pakistan',phone:'0300-0000000',logo:'',currency:'USD',footer:'THANK YOU!\nPLEASE VISIT AGAIN',low:10,tax:0},counter:0,products:[],sales:[],customers:[],expenses:[],offers:[]};
function seedOld(){return [
 {id:uid(),name:'Rice',sku:'RICE-01',category:'Grocery',unit:'KG',stock:200,desc:'Basmati rice',packs:[{label:'1 KG',size:1,price:350},{label:'5 KG',size:5,price:1700}]},
 {id:uid(),name:'Sugar',sku:'SUG-01',category:'Grocery',unit:'KG',stock:150,desc:'',packs:[{label:'1 KG',size:1,price:180},{label:'5 KG',size:5,price:850},{label:'10 KG',size:10,price:1650}]},
 {id:uid(),name:'Cooking Oil',sku:'OIL-01',category:'Grocery',unit:'Litre',stock:8,desc:'',packs:[{label:'1 Litre',size:1,price:520}]}]}
let S;
function load(){try{const j=localStorage.getItem(KEY);if(j){S=JSON.parse(j);S.settings=Object.assign({},DEF.settings,S.settings);if(S.settings.name==='ShopEase Mart')S.settings.name='AH Mart';['customers','expenses','offers'].forEach(k=>S[k]=S[k]||[]);if(S.products.length===3&&S.products.every(p=>['RICE-01','SUG-01','OIL-01'].includes(p.sku)))S.products=seed();if(S.settings.currency==='PKR'&&!S.sales.length)S.settings.currency='USD';return}}catch(e){}
 S=JSON.parse(JSON.stringify(DEF));S.products=seed()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){toast('Storage full or unavailable — data may not persist','e')}}
load();
const money=n=>{const c=S.settings.currency,v=Number(n||0).toLocaleString('en-US',{minimumFractionDigits:c==='USD'?2:0,maximumFractionDigits:2});return c==='USD'?'$'+v:c+' '+v};

/* ---------- ui helpers ---------- */
function toast(m,t){const d=document.createElement('div');d.textContent=m;if(t)d.className=t;$('#toast').appendChild(d);setTimeout(()=>d.remove(),3200)}
function modal(h,w){$('#modal').innerHTML=`<div class="mo" onclick="if(event.target===this)closeModal()"><div class="md" style="${w?'max-width:'+w:''}">${h}</div></div>`}
function closeModal(){$('#modal').innerHTML=''}
const stockBadge=p=>p.stock<=0?'<span class="badge out">Out of stock</span>':p.stock<=mn(p)?'<span class="badge low">Low</span>':'';

/* ---------- shell ---------- */
const VIEWS={dash:['Dashboard','home'],pos:['Sales','cart'],sales:['Sales History','receipt'],items:['Products','box'],inv:['Inventory','layers'],cust:['Customers','users'],reps:['Reports','chart'],exps:['Expenses','wallet'],offs:['Offers & Discounts','tag'],set:['Settings','set']};
let view='dash';
function shell(){const s=S.settings;
 $('#brand').innerHTML=(s.logo?`<img src="${esc(s.logo)}" alt="" style="width:36px;height:36px;object-fit:contain;border-radius:8px;background:#fff">`:logoSVG().replace('40','36').replace('40','36'))+`<div>${esc(s.name)}<small>Smart Shopping · Better Living</small></div>`;
 $('#nav').innerHTML=Object.entries(VIEWS).map(([k,v])=>(GL[k]?`<div class="gl">${GL[k]}</div>`:'')+`<button class="${k===view?'on':''}" onclick="go('${k}')">${ic(v[1])}<span>${v[0]}</span></button>`).join('')}
function go(v){view=v;cart=[];shell();bell();$('#title').textContent=VIEWS[v][0];({dash,pos,items,sales,set,inv,cust,reps,exps,offs})[v]()}
setInterval(()=>{const n=Date.now();$('#clock').innerHTML='<b>'+new Intl.DateTimeFormat('en-US',{timeZone:TZ,month:'short',day:'numeric',year:'numeric'}).format(n)+'</b><br>'+fTime(n)},1000);

/* ---------- dashboard ---------- */
function dashOld(){
 const today=fDate(Date.now()),ts=S.sales.filter(x=>fDate(x.ts)===today&&!x.void);
 const low=S.products.filter(p=>p.stock<=S.settings.low);const days=[...Array(7)].map((_,i)=>{const d=fDate(Date.now()-(6-i)*864e5);return{d:d.slice(0,5),v:S.sales.filter(x=>!x.void&&fDate(x.ts)===d).reduce((a,x)=>a+x.total,0)}}),mx=Math.max(1,...days.map(x=>x.v));
 const rows=S.sales.slice(-6).reverse().map(x=>`<tr><td>${esc(x.no)}</td><td>${fTime(x.ts)}</td><td class="r">${money(x.total)}</td></tr>`).join('')||'<tr><td colspan=3 class="empty">No sales yet</td></tr>';
 const lrows=low.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stock} ${esc(p.unit)}</td><td>${stockBadge(p)}</td></tr>`).join('')||'<tr><td colspan=3 class="empty">All stocked up 🎉</td></tr>';
 $('#page').innerHTML=`<div class='hero'><div><h2>${(h=>h<12?'Good morning':h<18?'Good afternoon':'Good evening')(+new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'numeric',hour12:false}).format(Date.now())%24)} 👋</h2><p>${esc(S.settings.name)} · ${fDate(Date.now())}</p></div><button class='btn' onclick="go('pos')">${ic('cart')} New Sale</button></div><div class="grid4">
 <div class="card stat"><span class='chip'>💰</span><div class="l">Today's Sales</div><div class="v">${money(ts.reduce((a,x)=>a+x.total,0))}</div></div>
 <div class="card stat"><span class='chip'>🧾</span><div class="l">Number of Sales</div><div class="v">${ts.length}</div></div>
 <div class="card stat"><span class='chip'>📦</span><div class="l">Total Products</div><div class="v">${S.products.length}</div></div>
 <div class="card stat"><span class='chip'>⚠️</span><div class="l">Low Stock Items</div><div class="v" style="color:${low.length?'var(--warn)':'inherit'}">${low.length}</div></div></div>
 ${charts(days,mx)}<div class="two"><div class="card"><h3>Recent Sales</h3><div class="tw"><table><tr><th>Receipt</th><th>Time</th><th class="r">Total</th></tr>${rows}</table></div></div>
 <div class="card"><h3>Low Stock</h3><div class="tw"><table><tr><th>Product</th><th>Stock</th><th></th></tr>${lrows}</table></div></div></div>
 <p style="margin-top:16px"><button class="btn" onclick="go('pos')">${ic('cart')} Start New Sale</button></p>`}

/* ---------- POS ---------- */
let cart=[];
function pos(){
 $('#page').innerHTML=`<div class="pos"><div><div class="bar"><input id="q" placeholder="Search product by name, SKU or category…" oninput="grid()" onkeydown="skuEnter(event)" autofocus></div><div class="pgrid" id="pg"></div></div>
 <div class="card cart"><h3>Cart</h3><div class="tw" id="cl"></div>
 ${S.offers.length?`<label>Offer</label><select id='of' onchange='applyOffer()'><option value=''>No offer</option>${S.offers.map((o,i)=>`<option value='${i}'>${esc(o.name)} (${o.type==='%'?o.value+'%':money(o.value)})</option>`).join('')}</select>`:''}<label>Discount (${esc(S.settings.currency)})</label><input id="disc" type="number" min="0" step="any" placeholder="0" oninput="totals()">
 <div id="tt" style="margin-top:8px"></div>
 <label>Payment method</label><select id="pm" onchange="totals()"><option>Cash</option><option>Card</option><option>Other</option></select>
 <div id="cashbox"><label>Amount paid</label><input id="paid" type="number" min="0" step="any" oninput="totals()"><div class="tot" style="margin-top:6px"><span>Change</span><b id="chg">—</b></div></div>
 <details style="margin:10px 0"><summary style="cursor:pointer;color:var(--mut)">Customer details (optional)</summary>
 <label>Name</label><input id="cn"><label>Phone</label><input id="cp" type="tel"><label>Address</label><input id="ca"></details>
 <button class="btn ok full" onclick="checkout()">Complete Sale</button></div></div>`;
 grid();drawCart()}
function grid(){const q=($('#q')||{value:''}).value.trim().toLowerCase();
 const l=S.products.filter(p=>!q||[p.name,p.sku,p.category].some(x=>(x||'').toLowerCase().includes(q)));
 $('#pg').innerHTML=l.map(p=>`<div class="pc"><b>${esc(p.name)}</b><div class="m">${esc(p.sku)} · ${esc(p.category)}<br>Stock: ${p.stock} ${esc(p.unit)} ${stockBadge(p)}</div>
 <select id="pk-${p.id}">${p.packs.map((k,i)=>`<option value="${i}">${esc(k.label)} — ${money(k.price)}</option>`).join('')}</select>
 <div class="row"><input id="qt-${p.id}" type="number" min="1" step="any" value="1" aria-label="Quantity"><button class="btn" style="flex:1" onclick="addCart('${p.id}')" ${p.stock<=0?'disabled':''}>${ic('plus')} Add</button></div></div>`).join('')||'<div class="empty">No products found</div>'}
const used=(pid,skip)=>cart.reduce((a,c,i)=>a+(c.pid===pid&&i!==skip?c.qty*c.size:0),0);
function addCart(pid){const p=S.products.find(x=>x.id===pid);if(!p)return;
 const k=p.packs[+$('#pk-'+pid).value],qty=num($('#qt-'+pid).value);
 if(!(qty>0))return toast('Enter a valid quantity greater than 0','e');
 if(used(pid)+qty*k.size>p.stock)return toast(`Only ${r2(p.stock-used(pid))} ${p.unit} of ${p.name} available`,'e');
 const ex=cart.find(c=>c.pid===pid&&c.label===k.label);
 if(ex)ex.qty=r2(ex.qty+qty);else cart.push({pid,name:p.name,label:k.label,size:k.size,price:k.price,qty});
 $('#qt-'+pid).value=1;drawCart()}
function setQty(i,v){const c=cart[i],p=S.products.find(x=>x.id===c.pid),n=num(v);
 if(!(n>0)){toast('Invalid quantity','e');return drawCart()}
 if(used(c.pid,i)+n*c.size>p.stock){toast(`Only ${r2((p.stock-used(c.pid,i))/c.size)} × ${c.label} available`,'e');return drawCart()}
 c.qty=n;drawCart()}
function rm(i){cart.splice(i,1);drawCart()}
function drawCart(){
 $('#cl').innerHTML=cart.length?`<table><tr><th>Item</th><th>Qty</th><th class="r">Total</th><th></th></tr>`+cart.map((c,i)=>`<tr><td>${esc(c.name)}<br><small style="color:var(--mut)">${esc(c.label)} @ ${money(c.price)}</small></td>
 <td><input type="number" min="0" step="any" value="${c.qty}" style="width:64px;padding:4px 6px" onchange="setQty(${i},this.value)"></td><td class="r">${money(c.qty*c.price)}</td>
 <td><button class="btn g sm" aria-label="Remove" onclick="rm(${i})">${ic('trash')}</button></td></tr>`).join('')+'</table>':'<div class="empty">Cart is empty</div>';
 totals()}
function calc(){const sub=r2(cart.reduce((a,c)=>a+c.qty*c.price,0));let d=num($('#disc').value);if(!(d>0))d=0;const dd=Math.min(d,sub),tax=r2((sub-dd)*(S.settings.tax||0)/100);return{sub,d:dd,rawD:d,tax,total:r2(sub-dd+tax)}}
function totals(){if($('#of')&&$('#of').value!==''){const o=S.offers[+$('#of').value],s0=cart.reduce((a,c)=>a+c.qty*c.price,0);$('#disc').value=r2(o.type==='%'?s0*o.value/100:Math.min(o.value,s0))}const t=calc(),cash=$('#pm').value==='Cash';$('#cashbox').style.display=cash?'':'none';
 $('#tt').innerHTML=`<div class="tot"><span>Subtotal</span><span>${money(t.sub)}</span></div><div class="tot"><span>Discount</span><span>- ${money(t.d)}</span></div>${t.tax?`<div class="tot"><span>Tax (${S.settings.tax}%)</span><span>${money(t.tax)}</span></div>`:''}<div class="tot g"><span>Grand Total</span><span>${money(t.total)}</span></div>`;
 const p=num($('#paid').value);$('#chg').textContent=isFinite(p)&&p>=t.total?money(r2(p-t.total)):'—'}
function checkout(){
 if(!cart.length)return toast('Cart is empty','e');
 const t=calc();if(t.rawD<0||t.rawD>t.sub)return toast('Discount cannot exceed the subtotal','e');
 for(const c of cart){const p=S.products.find(x=>x.id===c.pid);if(!p||used(c.pid)>p.stock)return toast('Insufficient stock for '+c.name,'e')}
 const m=$('#pm').value;let paid=t.total;
 if(m==='Cash'){paid=num($('#paid').value);if(!isFinite(paid)||paid<0)return toast('Enter a valid amount paid','e');if(paid<t.total)return toast('Amount paid is less than the grand total','e')}
 S.counter++;cart.forEach(c=>{S.products.find(x=>x.id===c.pid).stock=r2(S.products.find(x=>x.id===c.pid).stock-c.qty*c.size)});
 const sale={id:uid(),no:'POS-'+String(S.counter).padStart(5,'0'),ts:Date.now(),items:cart.map(c=>({...c})),
  cust:{name:$('#cn').value.trim(),phone:$('#cp').value.trim(),address:$('#ca').value.trim()},sub:t.sub,disc:t.d,tax:t.tax,taxRate:S.settings.tax||0,total:t.total,method:m,paid:r2(paid),change:r2(paid-t.total)};
 S.sales.push(sale);addCust(sale.cust);save();cart=[];showReceipt(sale,true);pos()}

/* ---------- receipt ---------- */
function receiptHTML(x){const s=S.settings,m=n=>Number(n).toLocaleString('en-PK',{maximumFractionDigits:2});
 return `<div id="receipt">${x.void?'<div class="c b">*** VOIDED ***</div>':''}<div class="c">${s.logo?`<img src="${esc(s.logo)}" alt="">`:logoSVG()}<div class="b">${esc(s.name).toUpperCase()}</div><div>${esc(s.address)}</div><div>Phone: ${esc(s.phone)}</div></div><hr>
 <div class="t"><span>Receipt #:</span><span>${esc(x.no)}</span></div><div class="t"><span>Date:</span><span>${fDate(x.ts)}</span></div><div class="t"><span>Time:</span><span>${fTime(x.ts)}</span></div>
 ${x.cust.name?`<div class="t"><span>Customer:</span><span>${esc(x.cust.name)}</span></div>`:''}${x.cust.phone?`<div class="t"><span>Phone:</span><span>${esc(x.cust.phone)}</span></div>`:''}${x.cust.address?`<div>${esc(x.cust.address)}</div>`:''}<hr>
 <table><tr><th>Item</th><th>Pack</th><th class="r">Qty</th><th class="r">Price</th><th class="r">Total</th></tr>${x.items.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.label)}</td><td class="r">${c.qty}</td><td class="r">${m(c.price)}</td><td class="r">${m(r2(c.qty*c.price))}</td></tr>`).join('')}</table><hr>
 <div class="t"><span>Subtotal:</span><span>${m(x.sub)}</span></div><div class="t"><span>Discount:</span><span>${m(x.disc)}</span></div>${x.tax?`<div class="t"><span>Tax (${x.taxRate}%):</span><span>${m(x.tax)}</span></div>`:''}<div class="t b"><span>TOTAL (${esc(s.currency)}):</span><span>${m(x.total)}</span></div><hr>
 <div class="t"><span>Payment:</span><span>${esc(x.method)}</span></div><div class="t"><span>Paid:</span><span>${m(x.paid)}</span></div><div class="t"><span>Change:</span><span>${m(x.change)}</span></div><hr>
 <div class="c b" style="font-size:12px">${esc(s.footer).replace(/\n/g,'<br>')}</div></div>`}
function showReceipt(x,isNew){modal(`${receiptHTML(x)}<div class="acts"><button class="btn" onclick="window.print()">${ic('print')} Print Receipt</button>${isNew?`<button class="btn ok" onclick="closeModal()">New Sale</button>`:`<button class="btn g" onclick="closeModal()">Close</button>`}</div>`,'400px')}
function viewSale(id){showReceipt(S.sales.find(x=>x.id===id),false)}

/* ---------- products ---------- */
function items(){const q=($('#iq')||{value:''}).value;
 $('#page').innerHTML=`<div class="bar"><input id="iq" placeholder="Search products…" oninput="itemRows()"><button class="btn" onclick="prodForm()">${ic('plus')} Add Product</button></div><div class="card tw" id="it"></div>`;itemRows()}
function itemRows(){const q=$('#iq').value.trim().toLowerCase();
 const l=S.products.filter(p=>!q||[p.name,p.sku,p.category].some(x=>(x||'').toLowerCase().includes(q)));
 $('#it').innerHTML=l.length?`<table><tr><th>Product</th><th>SKU</th><th>Category</th><th>Packing &amp; Price</th><th class="r">Stock</th><th></th></tr>`+l.map(p=>`<tr><td><b>${esc(p.name)}</b><br><small style="color:var(--mut)">${esc(p.desc)}</small></td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td>
 <td>${p.packs.map(k=>`<div>${esc(k.label)} — ${money(k.price)}</div>`).join('')}</td><td class="r">${p.stock} ${esc(p.unit)} ${stockBadge(p)}</td>
 <td style="white-space:nowrap"><button class="btn g sm" onclick="prodForm('${p.id}')">Edit</button> <button class="btn g sm" aria-label="Delete" onclick="delProd('${p.id}')">${ic('trash')}</button></td></tr>`).join('')+'</table>':'<div class="empty">No products yet. Click “Add Product”.</div>'}
function packRow(l,s,p){return `<div class="prow"><input class="pl" placeholder="Label e.g. 5 KG" value="${esc(l)}"><input class="ps" type="number" min="0" step="any" placeholder="Size in unit" value="${esc(s)}"><input class="pp" type="number" min="0" step="any" placeholder="Price" value="${esc(p)}"><button type="button" class="btn g sm" onclick="this.parentNode.remove()">✕</button></div>`}
function prodForm(id){const p=S.products.find(x=>x.id===id)||{name:'',sku:'',category:'',unit:'KG',stock:0,desc:'',packs:[{label:'1 KG',size:1,price:''}]};
 modal(`<h3>${id?'Edit':'Add'} Product</h3><label>Product name *</label><input id="fn" value="${esc(p.name)}">
 <div class="two-in"><div><label>SKU / Code</label><input id="fs" value="${esc(p.sku)}"></div><div><label>Category</label><input id="fc" value="${esc(p.category)}"></div>
 <div><label>Unit (KG, Litre, Pcs…)</label><input id="fu" value="${esc(p.unit)}"></div><div><label>Stock (in unit) *</label><input id="fq" type="number" min="0" step="any" value="${p.stock}"></div></div>
 <div class='two-in'><div><label>Supplier</label><input id='fsu' value="${esc(p.supplier||'')}"></div><div><label>Min stock level</label><input id='fmn' type='number' min='0' step='any' value="${p.min==null?S.settings.low:p.min}"></div></div><label>Description</label><textarea id="fd" rows="2">${esc(p.desc)}</textarea>
 <label>Packing &amp; prices — label, size (in units, e.g. 5 for 5 KG), price</label><div id="pks">${p.packs.map(k=>packRow(k.label,k.size,k.price)).join('')}</div>
 <button class="btn g sm" type="button" onclick="$('#pks').insertAdjacentHTML('beforeend',packRow('','',''))">${ic('plus')} Add packing</button>
 <div class="acts"><button class="btn" onclick="saveProd('${id||''}')">Save</button><button class="btn g" onclick="closeModal()">Cancel</button></div>`)}
function saveProd(id){const name=$('#fn').value.trim(),stock=num($('#fq').value);
 if(!name)return toast('Product name is required','e');
 if(!isFinite(stock)||stock<0)return toast('Stock must be 0 or more','e');
 const packs=[...document.querySelectorAll('#pks .prow')].map(r=>({label:r.querySelector('.pl').value.trim(),size:num(r.querySelector('.ps').value),price:num(r.querySelector('.pp').value)}));
 if(!packs.length)return toast('Add at least one packing/price','e');
 for(const k of packs){if(!k.label)return toast('Every packing needs a label','e');if(!(k.size>0))return toast('Pack size must be greater than 0','e');if(!isFinite(k.price)||k.price<0)return toast('Price cannot be negative or empty','e')}
 const o={name,sku:$('#fs').value.trim()||name.slice(0,4).toUpperCase()+'-'+String(S.products.length+1).padStart(2,'0'),category:$('#fc').value.trim()||'General',unit:$('#fu').value.trim()||'Pcs',stock,desc:$('#fd').value.trim(),packs,supplier:$('#fsu').value.trim(),min:Math.max(0,num($('#fmn').value)||0)};
 if(id)Object.assign(S.products.find(x=>x.id===id),o);else S.products.push({id:uid(),...o});
 save();closeModal();toast('Product saved','s');items()}
function delProd(id){if(confirm('Delete this product?')){S.products=S.products.filter(x=>x.id!==id);save();items()}}

/* ---------- sales history ---------- */
function sales(){const fq=(($('#sq')||{}).value||'').trim().toLowerCase(),fd=(($('#sd')||{}).value||'');const l=[...S.sales].reverse().filter(x=>(!fq||x.no.toLowerCase().includes(fq)||(x.cust.name||'').toLowerCase().includes(fq)||(x.cust.phone||'').includes(fq))&&(!fd||fDate(x.ts)===fd.split('-').reverse().join('-')));
 $('#page').innerHTML=`<div class="bar"><input id="sq" placeholder="Search receipt #, customer or phone, then press Enter" value="${esc(fq)}" onchange="sales()"><input id="sd" type="date" value="${esc(fd)}" style="width:auto;flex:none" onchange="sales()"><button class="btn g" onclick="csvOut()">Export CSV</button></div><div class="card tw">${l.length?`<table><tr><th>Receipt</th><th>Date</th><th>Customer</th><th class="r">Total</th><th>Payment</th><th></th></tr>`+l.map(x=>`<tr><td><b>${esc(x.no)}</b></td><td>${fDate(x.ts)} ${fTime(x.ts)}</td><td>${esc(x.cust.name)||'Walk-in'}</td><td class="r">${x.void?'<s>'+money(x.total)+'</s> <span class="badge out">Void</span>':money(x.total)}</td><td>${esc(x.method)}</td>
 <td style="white-space:nowrap"><button class="btn g sm" onclick="viewSale('${x.id}')">View</button> ${x.void?'':`<button class="btn g sm" onclick="voidSale('${x.id}')">Void</button>`} <button class="btn g sm" onclick="viewSale('${x.id}');setTimeout(()=>window.print(),150)">${ic('print')} Print</button></td></tr>`).join('')+'</table>':'<div class="empty">No sales yet</div>'}</div>`}

/* ---------- settings ---------- */
function set(){const s=S.settings;
 $('#page').innerHTML=`<div class="card" style="max-width:640px"><h3>Business &amp; Receipt Settings</h3>
 <label>Business name</label><input id="sn" value="${esc(s.name)}"><label>Address</label><input id="sa" value="${esc(s.address)}"><label>Phone</label><input id="sp" value="${esc(s.phone)}">
 <div class="two-in"><div><label>Currency</label><input id="sc" value="${esc(s.currency)}"></div><div><label>Low-stock threshold</label><input id="sl" type="number" min="0" value="${s.low}"></div><div><label>Tax rate (%) — 0 for none</label><input id="st" type="number" min="0" max="100" step="any" value="${s.tax||0}"></div></div>
 <label>Receipt footer</label><textarea id="sf" rows="2">${esc(s.footer)}</textarea>
 <label>Logo (PNG/JPG, max 300 KB)</label><input id="sg" type="file" accept="image/*" onchange="logoUp(this)"><div id="lp" style="margin-top:6px">${s.logo?`<img src="${esc(s.logo)}" alt="" height="48"> <button class="btn g sm" onclick="S.settings.logo='';set()">Remove</button>`:''}</div>
 <div class="acts" style="justify-content:flex-start"><button class="btn" onclick="saveSet()">Save Settings</button><button class="btn g" onclick="demoHistory()">Load 30-day demo data</button><button class="btn g" onclick="loadSample()">Add 100 sample items</button><button class="btn g" onclick="clearAll()">Start fresh (empty)</button><button class="btn g" onclick="backup()">Backup data</button><button class="btn g" onclick="restoreForm()">Restore data</button><button class="btn g" onclick="resetAll()">Reset all data</button></div></div>`}
function logoUp(i){const f=i.files[0];if(!f)return;if(f.size>300000){i.value='';return toast('Logo is larger than 300 KB','e')}
 const r=new FileReader();r.onload=()=>{S.settings.logo=r.result;$('#lp').innerHTML=`<img src="${esc(r.result)}" alt="" height="48">`};r.readAsDataURL(f)}
function saveSet(){const s=S.settings,n=$('#sn').value.trim(),l=num($('#sl').value);
 if(!n)return toast('Business name is required','e');if(!(l>=0))return toast('Invalid low-stock threshold','e');
 Object.assign(s,{name:n,address:$('#sa').value.trim(),phone:$('#sp').value.trim(),currency:$('#sc').value.trim()||'PKR',footer:$('#sf').value,low:l,tax:Math.max(0,Math.min(100,num($('#st').value)||0))});save();shell();toast('Settings saved','s')}
function resetAll(){if(confirm('Delete ALL products, sales and settings and restore demo data?')){try{localStorage.removeItem(KEY)}catch(e){}load();if(!S.sales.length&&!S.customers.length)demoHistory(true);shell();go('dash')}}

function charts(days,mx){
 const act=S.sales.filter(x=>!x.void),W=420,H=170,px=i=>30+i*(W-60)/6,py=v=>H-30-v/mx*(H-60);
 const pts=days.map((d,i)=>[px(i),py(d.v)]),line=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' '),area=line+` L${px(6)} ${H-30} L${px(0)} ${H-30} Z`;
 const trend=`<svg viewBox='0 0 ${W} ${H}' style='width:100%;height:auto' role='img' aria-label='Sales over the last 7 days'><defs><linearGradient id='ag' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#14b8a6' stop-opacity='.45'/><stop offset='1' stop-color='#14b8a6' stop-opacity='0'/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1='30' x2='${W-30}' y1='${H-30-i*(H-60)/3}' y2='${H-30-i*(H-60)/3}' stroke='currentColor' opacity='.15'/>`).join('')}<path d='${area}' fill='url(#ag)'/><path d='${line}' fill='none' stroke='#0f766e' stroke-width='3' stroke-linejoin='round' stroke-linecap='round'/>${pts.map((p,i)=>`<circle cx='${p[0]}' cy='${p[1]}' r='4.5' fill='#fff' stroke='#0f766e' stroke-width='2.5'><title>${days[i].d}: ${money(days[i].v)}</title></circle><text x='${p[0]}' y='${H-10}' text-anchor='middle' font-size='10' fill='currentColor'>${days[i].d}</text>`).join('')}</svg>`;
 const pm={};act.forEach(x=>pm[x.method]=(pm[x.method]||0)+x.total);
 const tot=Object.values(pm).reduce((a,b)=>a+b,0),cols=['#0f766e','#f59e0b','#e11d48'],R=42,C=2*Math.PI*R;let off=0;
 const segs=Object.entries(pm).map(([k,v],i)=>{const len=v/tot*C,s=`<circle r='${R}' cx='60' cy='60' fill='none' stroke='${cols[i%3]}' stroke-width='18' stroke-dasharray='${len} ${C-len}' stroke-dashoffset='${-off}' transform='rotate(-90 60 60)'/>`;off+=len;return s}).join('');
 const donut=tot?`<svg viewBox='0 0 120 120' style='width:140px;display:block;margin:0 auto' role='img' aria-label='Payment methods'>${segs}<text x='60' y='64' text-anchor='middle' font-size='11' font-weight='700' fill='currentColor'>${act.length} sales</text></svg><div style='margin-top:8px'>${Object.entries(pm).map(([k,v],i)=>`<div class='tot'><span><i style='display:inline-block;width:10px;height:10px;border-radius:3px;background:${cols[i%3]};margin-right:6px'></i>${esc(k)}</span><b>${Math.round(v/tot*100)}%</b></div>`).join('')}</div>`:'<div class="empty">No sales yet</div>';
 const tp={};act.forEach(x=>x.items.forEach(c=>tp[c.name]=(tp[c.name]||0)+c.qty*c.price));
 const top=Object.entries(tp).sort((a,b)=>b[1]-a[1]).slice(0,5),tm=top.length?top[0][1]:1;
 const bars=top.length?top.map(([n,v])=>`<div style='margin-bottom:10px'><div class='tot' style='padding:0'><span>${esc(n)}</span><b>${money(v)}</b></div><div style='height:8px;border-radius:99px;background:var(--bd)'><div style='height:8px;border-radius:99px;width:${Math.max(4,Math.round(v/tm*100))}%;background:linear-gradient(90deg,#14b8a6,#f59e0b)'></div></div></div>`).join(''):'<div class="empty">No sales yet</div>';
 return `<div class='cg'><div class='card'><h3>Sales — last 7 days</h3><div style='color:var(--mut)'>${trend}</div></div><div class='card'><h3>Payment methods</h3>${donut}</div><div class='card'><h3>Top products</h3>${bars}</div></div>`}
const EMO=['🥤','🍿','🍫','🧴','🌾','🥛','🍎','🧼'],emo=s=>EMO[[...String(s)].reduce((a,c)=>a+c.charCodeAt(0),0)%8],COL=['#6366f1','#8b5cf6','#38bdf8','#34d399','#f472b6','#fbbf24','#94a3b8'];
const dk=t=>Math.floor((t+18e6)/864e5),sumB=(a,k)=>a.reduce((s,x)=>s+x[k],0),act=()=>S.sales.filter(x=>!x.void);
const mn=p=>p.min!=null?p.min:S.settings.low,lvl=p=>Math.min(100,Math.round(p.stock/Math.max(1,mn(p))*100)),pcol=v=>v<25?'#ef4444':v<50?'#f59e0b':'#16a34a';
let rng=0,rp=7;const RNG=[['7D',7,1],['30D',10,3],['3M',13,7],['1Y',12,30]];
function bell(){const n=S.products.filter(p=>p.stock<=mn(p)).length,b=$('#bell');b.textContent=n||''}
function gSearch(e){if(e.key==='Escape'){gClose();return}if(e.key!=='Enter')return;const v=e.target.value.trim();if(!v)return;const cs=custFind(v);if(cs.length){gClose();e.target.value='';custHist(cs[0]);return}gClose();go('pos');$('#q').value=v;grid();e.target.value=''}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#gs').focus()}});
function quickAdd(id){go('pos');addCart(id)}
function setRng(i){rng=i;dash()}
function buckets(){const [,b,s]=RNG[rng],td=dk(Date.now()),a=act();return [...Array(b)].map((_,i)=>{const e=td-(b-1-i)*s,st=e-s+1,m=a.filter(x=>{const d=dk(x.ts);return d>=st&&d<=e});return{l:fDate(e*864e5-18e6+432e5).slice(0,5),v:sumB(m,'total'),n:m.length}})}
function ovChart(){const B=buckets(),W=560,H=250,L=48,R=34,T=14,Bt=30,iw=W-L-R,ih=H-T-Bt,mv=Math.max(1,...B.map(x=>x.v)),mn=Math.max(1,...B.map(x=>x.n)),st=Math.pow(10,Math.floor(Math.log10(mv))),Mv=Math.ceil(mv/st)*st,Mn=Math.ceil(mn/4)*4,bw=iw/B.length,y=v=>T+ih-v/Mv*ih,yn=v=>T+ih-v/Mn*ih,k=v=>v>=1000?(v/1000)+'K':v;
 let g='';for(let i=0;i<=4;i++){const yy=T+ih-i*ih/4;g+=`<line x1='${L}' x2='${W-R}' y1='${yy}' y2='${yy}' stroke='currentColor' opacity='.12'/><text x='${L-6}' y='${yy+3}' text-anchor='end' font-size='9' fill='currentColor' opacity='.6'>${k(Mv*i/4)}</text><text x='${W-R+6}' y='${yy+3}' font-size='9' fill='currentColor' opacity='.6'>${Math.round(Mn*i/4)}</text>`}
 const bars=B.map((x,i)=>`<rect x='${L+i*bw+bw*.22}' y='${y(x.v)}' width='${bw*.56}' height='${T+ih-y(x.v)}' rx='4' fill='url(#bg)'><title>${x.l}: ${money(x.v)} · ${x.n} orders</title></rect><text x='${L+i*bw+bw/2}' y='${H-10}' text-anchor='middle' font-size='9' fill='currentColor' opacity='.6'>${B.length>12&&i%2?'':x.l}</text>`).join(''),pts=B.map((x,i)=>[L+i*bw+bw/2,yn(x.n)]);
 return `<svg viewBox='0 0 ${W} ${H}' style='width:100%;height:auto;color:var(--mut)' role='img' aria-label='Sales and orders'><defs><linearGradient id='bg' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#3b82f6'/><stop offset='1' stop-color='#1d6bf3'/></linearGradient></defs>${g}${bars}<polyline points='${pts.map(p=>p.join(',')).join(' ')}' fill='none' stroke='#16a34a' stroke-width='2.5' stroke-linejoin='round'/>${pts.map(p=>`<circle cx='${p[0]}' cy='${p[1]}' r='3.5' fill='#fff' stroke='#16a34a' stroke-width='2'/>`).join('')}</svg>`}
function spark(a,c){const m=Math.max(1,...a),p=a.map((v,i)=>`${i*100/(a.length-1)},${30-v/m*26}`).join(' ');return `<svg viewBox='0 0 100 32' preserveAspectRatio='none' style='position:absolute;right:10px;bottom:10px;width:44%;height:32px'><polyline points='${p}' fill='none' stroke='${c}' stroke-width='2' vector-effect='non-scaling-stroke'/></svg>`}
function dashB(){
 const td=dk(Date.now()),a=act(),on=d=>a.filter(x=>dk(x.ts)===d),rg=(f,t)=>a.filter(x=>dk(x.ts)>=f&&dk(x.ts)<=t);
 const d7=[...Array(7)].map((_,i)=>on(td-6+i)),s7=d7.map(m=>sumB(m,'total')),c7=d7.map(m=>m.length),w=sumB(rg(td-6,td),'total'),pw=sumB(rg(td-13,td-7),'total'),n=S.products.length,inS=S.products.filter(p=>p.stock>0).length,mo=S.customers.filter(c=>dk(c.ts||0)>=td-29).length;
 const exd=d=>sumB(S.expenses.filter(e=>dk(e.ts)===d),'amount'),pf=d=>r2(sumB(on(d),'total')-exd(d)),p0=pf(td),p1=pf(td-1),pc=(x,y)=>y?Math.round((x-y)/Math.abs(y)*100):null,tr=(p,l)=>p==null?'':`<span class='${p>=0?'up':'dn'}'>${p>=0?'↑':'↓'} ${Math.abs(p)}%</span> <small>${l}</small>`;
 const cards=[['#2563eb','cart','Total Sales',money(sumB(a,'total')),tr(pc(w,pw),'vs prev 7 days'),s7],['#16a34a','box','Total Products',n,`<span class='up'>↑ ${n?Math.round(inS/n*100):0}%</span> <small>in stock</small>`,c7],['#7c3aed','users','Total Customers',S.customers.length,`<span class='up'>↑ ${mo}</span> <small>new in 30 days</small>`,c7],['#f59e0b','dollar',`Today's Profit`,money(p0),tr(pc(p0,p1),'vs yesterday'),s7]];
 const cat={};a.forEach(x=>x.items.forEach(c=>{const p=S.products.find(q=>q.id===c.pid),k=p?p.category:'Other';cat[k]=(cat[k]||0)+c.qty*c.price}));
 let ce=Object.entries(cat).sort((p,q)=>q[1]-p[1]);if(ce.length>6){const o=ce.slice(6).reduce((s,e)=>s+e[1],0);ce=ce.slice(0,6).concat([['Others',o]])}
 const ct=ce.reduce((s,e)=>s+e[1],0);let ac=0;const cg=ce.map(([k,v],i)=>{const s=ac;ac+=v/ct*100;return `${COL[i]} ${s}% ${ac}%`}).join(',');
 const sold={};a.forEach(x=>x.items.forEach(c=>sold[c.pid]=(sold[c.pid]||0)+c.qty*c.size));
 const tp=[...S.products].sort((p,q)=>(sold[q.id]||0)-(sold[p.id]||0)).slice(0,5),al=[...S.products].sort((p,q)=>p.stock-q.stock).slice(0,4);
 const h=+new Intl.DateTimeFormat('en-US',{timeZone:TZ,hour:'numeric',hour12:false}).format(Date.now())%24,open=h>=8&&h<22,okc=S.products.filter(p=>p.stock>S.settings.low).length,sl=n?Math.round(okc/n*100):100,ofr=S.offers[0];
 const pmc={Cash:'g',Card:'',Other:'o'};
 $('#page').innerHTML=`<div class='dg'><div class='col'>
<div class='hero2'><div><small>Welcome to</small><h2>${esc(S.settings.name)}</h2><p>Your One Stop Shop</p><span>Fresh Products • Best Prices • Great Experience</span><br><button class='btn' onclick="go('pos')">Start New Sale →</button></div><div class='art'>🛒🥫<em>More Savings Everyday</em></div></div>
<div class='sg'>${cards.map(([c,i,l,v,t,sp])=>`<div class='sc' style='--c:${c}'><span class='ci'>${ic(i)}</span><div><div class='lb'>${l}</div><div class='vv'>${v}</div><div>${t}</div></div>${spark(sp,c)}</div>`).join('')}</div>
<div class='cg2'><div class='card'><div class='ch'><h3>${ic('chart')} Sales Overview</h3><div class='seg'>${RNG.map((r,i)=>`<button class='${i===rng?'on':''}' onclick='setRng(${i})'>${r[0]}</button>`).join('')}</div></div><div style='font-size:12px;color:var(--mut);margin-bottom:6px'><span style='color:#1d6bf3'>●</span> Sales (${esc(S.settings.currency)}) &nbsp; <span style='color:#16a34a'>●</span> Orders</div>${ovChart()}</div>
<div class='card'><div class='ch'><h3>Top Selling Categories</h3></div><div style='display:flex;gap:14px;align-items:center;flex-wrap:wrap'><div class='dnut' style='background:conic-gradient(${ct?cg:'var(--bd) 0 100%'})'><div><span><b>${money(ct)}</b>Total Sales</span></div></div><div class='leg'>${ce.length?ce.map(([k,v],i)=>`<div><span><i style='background:${COL[i]}'></i>${esc(k)}</span><b>${Math.round(v/ct*100)}%</b></div>`).join(''):'<div class="empty">No sales yet</div>'}</div></div></div></div>
<div class='cg2'><div class='card'><div class='ch'><h3>🏆 Top Products</h3><a onclick="go('items')">View All →</a></div><div class='tpg'>${tp.map(p=>`<div class='tp'><div class='ph'>${emo(p.category)}</div><b>${esc(p.name)}</b><small>In Stock: ${p.stock}</small><div class='pr'><span>${money(p.packs[0].price)}</span><button aria-label='Add to sale' onclick="quickAdd('${p.id}')">+</button></div></div>`).join('')||'<div class="empty">No products</div>'}</div></div>
<div class='card'><div class='ch'><h3>⚠️ Inventory Alert</h3><a onclick="go('inv')">View All →</a></div>${al.map(p=>{const v=lvl(p);return `<div class='ia'><span style='font-size:24px'>${emo(p.category)}</span><div><b>${esc(p.name)}</b><small>Stock: ${p.stock} ${esc(p.unit)} (${p.stock<=S.settings.low?'Low':'Normal'})</small></div><div class='bar2'><i style='width:${v}%;background:${pcol(v)}'></i></div><span>${v}%</span></div>`}).join('')||'<div class="empty">No products</div>'}</div></div></div>
<div class='col'><div class='card'><div class='ch'><h3>Quick Actions</h3></div><div class='qa'><button style='--c:#16a34a' onclick="go('pos')"><span class='ci'>${ic('plus')}</span><b>New Sale</b><small>Process a sale</small></button><button style='--c:#2563eb' onclick="go('items');prodForm()"><span class='ci'>${ic('box')}</span><b>Add Product</b><small>Add to inventory</small></button><button style='--c:#7c3aed' onclick="go('cust');custForm()"><span class='ci'>${ic('users')}</span><b>Add Customer</b><small>Manage customers</small></button><button style='--c:#f59e0b' onclick="go('reps')"><span class='ci'>${ic('chart')}</span><b>View Reports</b><small>Sales &amp; inventory</small></button></div></div>
<div class='card ss'><div><b>Store Status</b><div style='margin:6px 0'><span class='${open?'up':'dn'}'>● ${open?'Open':'Closed'}</span></div><small style='color:var(--mut)'>8:00 AM - 10:00 PM</small></div><div style='display:flex;gap:10px;align-items:center'><div class='ring' style='--p:${sl}'><span>${sl}%</span></div><div><small style='color:var(--mut)'>Stock Level</small><div><b>${sl>=70?'Good':sl>=40?'Fair':'Low'}</b></div></div></div></div>
<div class='card tw'><div class='ch'><h3>Recent Sales</h3><a onclick="go('sales')">View All →</a></div>${a.length?`<table><tr><th>#</th><th>Customer</th><th>Items</th><th>Total</th><th>Pay</th><th>Time</th></tr>${a.slice(-5).reverse().map(x=>`<tr><td>#${x.no.slice(-4)}</td><td>${esc(x.cust.name)||'Walk-in'}</td><td>${x.items.length}</td><td>${money(x.total)}</td><td><span class='pill ${pmc[x.method]||''}'>${esc(x.method)}</span></td><td>${fTime(x.ts)}</td></tr>`).join('')}</table>`:'<div class="empty">No sales yet</div>'}</div>
<div class='ofr'><span class='tag'>Special Offer</span><h4>${ofr?esc(ofr.name):'Create an offer'}</h4><div>${ofr?(ofr.type==='%'?'Up to '+ofr.value+'% off':money(ofr.value)+' off')+' on selected items':'Add discounts in Offers & Discounts'}</div><button class='btn' onclick="go('${ofr?'pos':'offs'}')">${ofr?'Shop Now':'Add Offer'} →</button><div class='art'>🧺</div></div></div></div>
<div class='foot'><span>© 2026 ${esc(S.settings.name)}. All rights reserved.</span><span>Privacy Policy · Terms &amp; Conditions · Help</span></div>`}
function applyOffer(){if($('#of').value==='')$('#disc').value='';totals()}
function custStats(c){const m=act().filter(x=>c.phone?x.cust.phone===c.phone:(x.cust.name||'').toLowerCase()===c.name.toLowerCase());return{n:m.length,v:sumB(m,'total')}}
function cust(){$('#page').innerHTML=`<div class='bar'><input id='cq' placeholder='Search customers…' oninput='custRows()'><button class='btn' onclick='custForm()'>${ic('plus')} Add Customer</button></div><div class='card tw' id='ct'></div>`;custRows()}
function custRows(){const q=$('#cq').value.trim().toLowerCase(),l=S.customers.filter(c=>!q||(c.name+c.phone).toLowerCase().includes(q));$('#ct').innerHTML=l.length?`<table><tr><th>Name</th><th>Phone</th><th>Address</th><th class='r'>Orders</th><th class='r'>Spent</th><th></th></tr>`+l.map(c=>{const s=custStats(c);return `<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone)}</td><td>${esc(c.address)}</td><td class='r'>${s.n}</td><td class='r'>${money(s.v)}</td><td style='white-space:nowrap'><button class='btn sm' onclick="custHistId('${c.id}')">History</button> <button class='btn g sm' onclick="custForm('${c.id}')">Edit</button> <button class='btn g sm' aria-label='Delete' onclick="delCust('${c.id}')">${ic('trash')}</button></td></tr>`}).join('')+'</table>':`<div class='empty'>No customers yet. They are added automatically when you enter customer details at checkout.</div>`}
function custForm(id){const c=S.customers.find(x=>x.id===id)||{name:'',phone:'',address:''};modal(`<h3>${id?'Edit':'Add'} Customer</h3><label>Name *</label><input id='kn' value="${esc(c.name)}"><label>Phone</label><input id='kp' value="${esc(c.phone)}"><label>Address</label><input id='ka' value="${esc(c.address)}"><div class='acts'><button class='btn' onclick="saveCust('${id||''}')">Save</button><button class='btn g' onclick='closeModal()'>Cancel</button></div>`)}
function saveCust(id){const o={name:$('#kn').value.trim(),phone:$('#kp').value.trim(),address:$('#ka').value.trim()};if(!o.name)return toast('Customer name is required','e');if(id)Object.assign(S.customers.find(x=>x.id===id),o);else S.customers.push({id:uid(),ts:Date.now(),...o});save();closeModal();cust()}
function delCust(id){if(confirm('Delete this customer?')){S.customers=S.customers.filter(x=>x.id!==id);save();cust()}}
function addCust(c){if(!c.name&&!c.phone)return;if(S.customers.find(x=>c.phone?x.phone===c.phone:x.name.toLowerCase()===c.name.toLowerCase()))return;S.customers.push({id:uid(),ts:Date.now(),name:c.name||'Customer '+c.phone,phone:c.phone,address:c.address})}
function invOld(){const l=[...S.products].sort((p,q)=>p.stock-q.stock);$('#page').innerHTML=`<div class='card tw'><h3>Inventory</h3><table><tr><th>Product</th><th>Stock</th><th>Level</th><th>Status</th><th>Add stock</th></tr>`+l.map(p=>{const v=lvl(p);return `<tr><td><b>${esc(p.name)}</b><br><small style='color:var(--mut)'>${esc(p.sku)}</small></td><td>${p.stock} ${esc(p.unit)}</td><td style='min-width:120px'><div class='bar2'><i style='width:${v}%;background:${pcol(v)}'></i></div></td><td>${stockBadge(p)||`<span class='pill g'>OK</span>`}</td><td style='white-space:nowrap'><input id='rs-${p.id}' type='number' min='0' step='any' style='width:90px;display:inline-block' placeholder='+ qty'> <button class='btn sm' onclick="restock('${p.id}')">Add</button></td></tr>`}).join('')+'</table></div>'}
function restock(id){const n=num($('#rs-'+id).value);if(!(n>0))return toast('Enter a quantity greater than 0','e');const p=S.products.find(x=>x.id===id);p.stock=r2(p.stock+n);save();toast('Stock updated','s');inv()}
function exps(){const td=dk(Date.now()),l=[...S.expenses].reverse(),t=sumB(S.expenses.filter(e=>dk(e.ts)===td),'amount');$('#page').innerHTML=`<div class='two'><div class='card'><h3>Add Expense</h3><label>Title *</label><input id='et' placeholder='e.g. Electricity bill'><label>Category</label><input id='ec' placeholder='Rent, Utilities, Salary…'><label>Amount (${esc(S.settings.currency)}) *</label><input id='ea' type='number' min='0' step='any'><div class='acts' style='justify-content:flex-start'><button class='btn' onclick='addExp()'>${ic('plus')} Add Expense</button></div><p style='color:var(--mut)'>Today's expenses: <b>${money(t)}</b>. Expenses are deducted from Today's Profit on the dashboard.</p></div><div class='card tw'><h3>Expense History</h3>${l.length?`<table><tr><th>Date</th><th>Title</th><th>Category</th><th class='r'>Amount</th><th></th></tr>${l.map(e=>`<tr><td>${fDate(e.ts)}</td><td>${esc(e.title)}</td><td>${esc(e.cat)}</td><td class='r'>${money(e.amount)}</td><td><button class='btn g sm' aria-label='Delete' onclick="delExp('${e.id}')">${ic('trash')}</button></td></tr>`).join('')}</table>`:`<div class='empty'>No expenses yet</div>`}</div></div>`}
function addExp(){const t=$('#et').value.trim(),a=num($('#ea').value);if(!t)return toast('Expense title is required','e');if(!(a>0))return toast('Enter an amount greater than 0','e');S.expenses.push({id:uid(),title:t,cat:$('#ec').value.trim()||'General',amount:a,ts:Date.now()});save();toast('Expense added','s');exps()}
function delExp(id){if(confirm('Delete this expense?')){S.expenses=S.expenses.filter(e=>e.id!==id);save();exps()}}
function offs(){$('#page').innerHTML=`<div class='two'><div class='card'><h3>New Offer / Discount</h3><label>Name *</label><input id='on' placeholder='e.g. Eid Sale'><div class='two-in'><div><label>Type</label><select id='ot'><option value='%'>Percent (%)</option><option value='Rs'>Fixed amount</option></select></div><div><label>Value *</label><input id='ov' type='number' min='0' step='any'></div></div><div class='acts' style='justify-content:flex-start'><button class='btn' onclick='addOff()'>${ic('plus')} Add Offer</button></div><p style='color:var(--mut)'>Offers appear as a dropdown on the Sales screen and fill in the discount automatically.</p></div><div class='card tw'><h3>Active Offers</h3>${S.offers.length?`<table><tr><th>Name</th><th>Discount</th><th></th></tr>${S.offers.map((o,i)=>`<tr><td>${esc(o.name)}</td><td>${o.type==='%'?o.value+'%':money(o.value)}</td><td><button class='btn g sm' aria-label='Delete' onclick='delOff(${i})'>${ic('trash')}</button></td></tr>`).join('')}</table>`:`<div class='empty'>No offers yet</div>`}</div></div>`}
function addOff(){const n=$('#on').value.trim(),t=$('#ot').value,v=num($('#ov').value);if(!n)return toast('Offer name is required','e');if(!(v>0)||(t==='%'&&v>100))return toast('Enter a valid discount value','e');S.offers.push({name:n,type:t,value:v});save();toast('Offer added','s');offs()}
function delOff(i){S.offers.splice(i,1);save();offs()}
function setRp(v){rp=v;reps()}
function reps(){const td=dk(Date.now()),f=rp?td-rp+1:-1e9,a=act().filter(x=>dk(x.ts)>=f),s=sumB(a,'total'),e=sumB(S.expenses.filter(x=>dk(x.ts)>=f),'amount');
 const by=fn=>{const o={};a.forEach(x=>fn(x).forEach(([k,v])=>o[k]=(o[k]||0)+v));return Object.entries(o).sort((p,q)=>q[1]-p[1])};
 const cat=by(x=>x.items.map(c=>{const p=S.products.find(q=>q.id===c.pid);return[p?p.category:'Other',c.qty*c.price]})),pm=by(x=>[[x.method,x.total]]),pr=by(x=>x.items.map(c=>[c.name,c.qty*c.price])).slice(0,10);
 const tbl=(t,l)=>`<div class='card tw'><h3>${t}</h3>${l.length?`<table>${l.map(([k,v])=>`<tr><td>${esc(k)}</td><td class='r'>${money(v)}</td></tr>`).join('')}</table>`:`<div class='empty'>No data</div>`}</div>`;
 $('#page').innerHTML=`<div class='bar'><select style='max-width:200px' onchange='setRp(+this.value)'>${[[1,'Today'],[7,'Last 7 days'],[30,'Last 30 days'],[0,'All time']].map(([v,l])=>`<option value='${v}' ${v===rp?'selected':''}>${l}</option>`).join('')}</select></div><div class='grid4'>${[['Sales',money(s)],['Orders',a.length],['Average order',money(a.length?r2(s/a.length):0)],['Expenses',money(e)],['Net profit',money(r2(s-e))]].map(([l,v])=>`<div class='card'><div style='color:var(--mut);font-size:12px'>${l}</div><div style='font-size:22px;font-weight:800'>${v}</div></div>`).join('')}</div><div class='two'>${tbl('Sales by category',cat)}${tbl('Payment methods',pm)}${tbl('Top products',pr)}</div>`}
