const ago=t=>{const m=Math.max(0,Math.round((Date.now()-t)/6e4));return m<1?'just now':m<60?m+'m ago':m<1440?Math.round(m/60)+'h ago':Math.round(m/1440)+'d ago'};
const sm=p=>p.map((q,i)=>i?`C${(p[i-1][0]+q[0])/2} ${p[i-1][1]} ${(p[i-1][0]+q[0])/2} ${q[1]} ${q[0]} ${q[1]}`:`M${q[0]} ${q[1]}`).join(' ');
const ser=(v,w,h,pd)=>{const m=Math.max(1,...v);return v.map((x,i)=>[+(i*w/(v.length-1)).toFixed(1),+(h-pd-x/m*(h-2*pd)).toFixed(1)])};
