const wave=v=>{const d=sm(ser(v,300,90,14));return `<svg viewBox='0 0 300 90' preserveAspectRatio='none' class='ar'><defs><linearGradient id='wv' x1='0' x2='1'><stop offset='0' stop-color='#6366f1'/><stop offset='1' stop-color='#38bdf8'/></linearGradient></defs>${[-14,-7,0,7,14].map(o=>`<path d='${d}' transform='translate(0 ${o})' fill='none' stroke='url(#wv)' stroke-width='${o?2.2:3}' stroke-dasharray='.1 4.5' stroke-linecap='round' opacity='${o?.55:1}' vector-effect='non-scaling-stroke'/>`).join('')}</svg>`};
const lineC=v=>`<svg viewBox='0 0 200 90' preserveAspectRatio='none' class='ar'><path d='${sm(ser(v,200,90,10))}' fill='none' stroke='#a5b4fc' stroke-width='1.8' stroke-dasharray='3 3' vector-effect='non-scaling-stroke'/></svg>`;
const mini=v=>`<svg viewBox='0 0 80 24' width='80' height='24'><path d='${sm(ser(v,80,24,3))}' fill='none' stroke='#a5b4fc' stroke-width='1.6'/></svg>`;
function funnel(){const cs=S.customers.map(c=>custStats(c).n),v=[cs.length,cs.filter(n=>n>=1).length,cs.filter(n=>n>=2).length,cs.filter(n=>n>=3).length],nm=['Customers','Purchased','Repeat (2+)','Loyal (3+)'],hh=v.map(x=>v[0]?Math.max(6,x/v[0]*80):6),X=[0,100,300,500,700,800],H=[hh[0],hh[0],hh[1],hh[2],hh[3],hh[3]],top=sm(X.map((x,i)=>[x,100-H[i]])),bot=sm(X.map((x,i)=>[x,100+H[i]]).reverse());
 return `<div class='fn'>${v.map((x,i)=>`<div><small>${i+1}. ${nm[i]}</small><b>${x}</b><span class='pcb'>${i?(v[i-1]?Math.round(x/v[i-1]*1000)/10:0):100}%</span></div>`).join('')}</div><svg viewBox='0 0 800 200' preserveAspectRatio='none' class='fs'><defs><linearGradient id='fg' x1='0' x2='1'><stop offset='0' stop-color='#6366f1'/><stop offset='.55' stop-color='#60a5fa'/><stop offset='1' stop-color='#34d399'/></linearGradient></defs><path d='${top} ${bot.replace('M','L')}Z' fill='url(#fg)' opacity='.9'/>${[100,300,500,700].map(x=>`<line x1='${x}' x2='${x}' y1='0' y2='200' stroke='currentColor' stroke-dasharray='4 5' opacity='.3' vector-effect='non-scaling-stroke'/>`).join('')}</svg><div class='ov'><span>Overall Conversion Rate</span><b>${v[0]?Math.round(v[3]/v[0]*1000)/10:0}%</b></div>`}
