 const a=act(),t=Date.now(),td=dk(t),tot=sumB(a,'total'),d14=dayTot(a,14),w=sumB(d14.slice(7),'total'),pw=sumB(d14.slice(0,7),'total'),pc=(x,y)=>y?Math.round((x-y)/y*1000)/10:null;
 const tr=(p,l)=>p==null?`<span class='sub'>${l}</span>`:`<span class='${p>=0?'up':'dn'}'>${p>=0?'↑':'↓'} ${Math.abs(p)}%</span> <span class='sub'>${l}</span>`;
 const mk=mkey(t),pk=mkey(t-(+fDate(t).slice(0,2))*864e5),mt=sumB(a.filter(x=>mkey(x.ts)===mk),'total'),pmt=sumB(a.filter(x=>mkey(x.ts)===pk),'total');
 const avg=(f,e)=>{const m=a.filter(x=>dk(x.ts)>=f&&dk(x.ts)<=e);return m.length?sumB(m,'total')/m.length:0},aov=a.length?tot/a.length:0,dA=[...Array(14)].map((_,i)=>avg(td-13+i,td-13+i));
 const act30=S.customers.filter(c=>a.some(x=>(c.phone?x.cust.phone===c.phone:(x.cust.name||'').toLowerCase()===c.name.toLowerCase())&&dk(x.ts)>=td-29)).length,nd=S.customers.length?Math.round(act30/S.customers.length*60):0;
 const pp={};a.filter(inPer).forEach(x=>x.items.forEach(c=>pp[c.name]=(pp[c.name]||0)+c.qty*c.price));
 const pl=Object.entries(pp).sort((p,q)=>q[1]-p[1]);let pe=pl.slice(0,4);if(pl.length>4)pe=pe.concat([['Others',pl.slice(4).reduce((s,e)=>s+e[1],0)]]);
 const pt=pl.reduce((s,e)=>s+e[1],0);let ac=0;const cg=pe.map(([k,v],i)=>{const s=ac;ac+=v/pt*100;return `${COL[i]} ${s}% ${ac}%`}).join(','),mx=(pl[0]||[0,1])[1];
 const ns=S.sales.length,BC=['#4f46e5','#34d399','#60a5fa','#3b3fb8'],SL=[[0,36],[100,0],[84,106],[162,74]],bc=[['Cash',S.sales.filter(x=>x.method==='Cash'&&!x.void).length],['Card',S.sales.filter(x=>x.method==='Card'&&!x.void).length],['Other',S.sales.filter(x=>x.method==='Other'&&!x.void).length],['Voided',S.sales.filter(x=>x.void).length]].filter(e=>e[1]).sort((p,q)=>q[1]-p[1]);
