 const sold7=p=>[...Array(7)].map((_,i)=>a.filter(x=>dk(x.ts)===td-6+i).reduce((s,x)=>s+x.items.filter(c=>c.pid===p.id).reduce((u,c)=>u+c.qty*c.size,0),0)),last=p=>{const m=a.filter(x=>x.items.some(c=>c.pid===p.id));return m.length?ago(m[m.length-1].ts):'Never'},rk=[...S.products].sort((p,q)=>lvl(p)-lvl(q)).slice(0,5);
